+//! Product-level release identity.
+//!
+//! A Callisto product release is intentionally distinct from a package release:
+//! one product tag identifies the coordinated output of a workspace, while a
+//! package may be published to several registries with their own grammars.
+
+use std::cmp::Ordering;
+use std::fmt;
+use std::str::FromStr;
+
+use schemars::JsonSchema;
+use serde::{Deserialize, Deserializer, Serialize, Serializer};
+
+use crate::{TagName, Version, VersionGrammar};
+
+/// A canonical product name used in product release tags.
+///
+/// Product names are deliberately narrower than package names. They become a
+/// git tag component and therefore use lowercase ASCII letters, digits, and
+/// interior hyphens only.
+#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, JsonSchema)]
+#[schemars(with = "String")]
+pub struct ProductName(String);
+
+impl ProductName {
+    /// Parses one canonical product name.
+    pub fn parse(raw: &str) -> Result<Self, ProductNameError> {
+        if raw.is_empty() {
+            return Err(ProductNameError::Empty);
+        }
+        if raw.starts_with('-') || raw.ends_with('-') {
+            return Err(ProductNameError::BoundaryHyphen {
+                raw: raw.to_string(),
+            });
+        }
+        if !raw
+            .bytes()
+            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
+        {
+            return Err(ProductNameError::InvalidCharacter {
+                raw: raw.to_string(),
+            });
+        }
+        Ok(Self(raw.to_string()))
+    }
+
+    /// Returns the canonical name.
+    pub fn as_str(&self) -> &str {
+        &self.0
+    }
+}
+
+impl fmt::Display for ProductName {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.write_str(&self.0)
+    }
+}
+
+impl FromStr for ProductName {
+    type Err = ProductNameError;
+
+    fn from_str(raw: &str) -> Result<Self, Self::Err> {
+        Self::parse(raw)
+    }
+}
+
+impl Serialize for ProductName {
+    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
+    where
+        S: Serializer,
+    {
+        serializer.serialize_str(&self.0)
+    }
+}
+
+impl<'de> Deserialize<'de> for ProductName {
+    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
+    where
+        D: Deserializer<'de>,
+    {
+        Self::parse(&String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
+    }
+}
+
+/// One immutable product release identity.
+///
+/// Its canonical tag spelling is `<product>@<semver>`. Product versions are
+/// always SemVer even when a constituent package uses another native grammar;
+/// registry-specific version adaptation belongs above this model boundary.
+#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
+#[schemars(with = "String")]
+pub struct ProductReleaseId {
+    product: ProductName,
+    version: Version,
+}
+
+impl ProductReleaseId {
+    /// Creates a product identity from a product name and a SemVer version.
+    pub fn new(product: ProductName, version: Version) -> Result<Self, ProductReleaseIdError> {
+        if version.grammar() != VersionGrammar::SemVer {
+            return Err(ProductReleaseIdError::NonSemVer {
+                grammar: version.grammar(),
+            });
+        }
+        Ok(Self { product, version })
+    }
+
+    /// Parses the canonical `<product>@<semver>` identity spelling.
+    pub fn parse(raw: &str) -> Result<Self, ProductReleaseIdError> {
+        let (product, version) = raw
+            .split_once('@')
+            .ok_or_else(|| ProductReleaseIdError::MissingSeparator {
+                raw: raw.to_string(),
+            })?;
+        if version.contains('@') {
+            return Err(ProductReleaseIdError::MultipleSeparators {
+                raw: raw.to_string(),
+            });
+        }
+        let product = ProductName::parse(product).map_err(ProductReleaseIdError::ProductName)?;
+        let version = Version::parse(version, VersionGrammar::SemVer).map_err(ProductReleaseIdError::Version)?;
+        Self::new(product, version)
+    }
+
+    /// Returns the product component.
+    pub fn product(&self) -> &ProductName {
+        &self.product
+    }
+
+    /// Returns the product's canonical SemVer version.
+    pub fn version(&self) -> &Version {
+        &self.version
+    }
+
+    /// Returns the git tag name represented by this identity.
+    pub fn tag_name(&self) -> TagName {
+        // ProductName and a SemVer rendering contain only characters accepted
+        // by Git ref names; `@` is an interior character in this fixed shape.
+        TagName::new_unchecked(self.to_string())
+    }
+}
+
+impl fmt::Display for ProductReleaseId {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        write!(f, "{}@{}", self.product, self.version.render())
+    }
+}
+
+impl FromStr for ProductReleaseId {
+    type Err = ProductReleaseIdError;
+
+    fn from_str(raw: &str) -> Result<Self, Self::Err> {
+        Self::parse(raw)
+    }
+}
+
+impl PartialOrd for ProductReleaseId {
+    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
+        Some(self.cmp(other))
+    }
+}
+
+impl Ord for ProductReleaseId {
+    fn cmp(&self, other: &Self) -> Ordering {
+        (self.product(), self.version().render()).cmp(&(other.product(), other.version().render()))
+    }
+}
+
+impl Serialize for ProductReleaseId {
+    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
+    where
+        S: Serializer,
+    {
+        serializer.serialize_str(&self.to_string())
+    }
+}
+
+impl<'de> Deserialize<'de> for ProductReleaseId {
+    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
+    where
+        D: Deserializer<'de>,
+    {
+        Self::parse(&String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
+    }
+}
+
+/// Errors parsing [`ProductName`].
+#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
+#[non_exhaustive]
+pub enum ProductNameError {
+    #[error("product name is empty")]
+    Empty,
+    #[error("product name `{raw}` may not begin or end with `-`")]
+    BoundaryHyphen { raw: String },
+    #[error("product name `{raw}` must use lowercase ASCII letters, digits, and interior hyphens only")]
+    InvalidCharacter { raw: String },
+}
+
+/// Errors parsing or constructing [`ProductReleaseId`].
+#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
+#[non_exhaustive]
+pub enum ProductReleaseIdError {
+    #[error("product release identity `{raw}` must be `<product>@<semver>")]
+    MissingSeparator { raw: String },
+    #[error("product release identity `{raw}` has more than one `@` separator")]
+    MultipleSeparators { raw: String },
+    #[error(transparent)]
+    ProductName(#[from] ProductNameError),
+    #[error(transparent)]
+    Version(#[from] crate::VersionParseError),
+    #[error("product releases require SemVer, not {grammar:?}")]
+    NonSemVer { grammar: VersionGrammar },
+}
