+        assert_eq!(ProductName::parse("callisto-cli").unwrap().as_str(), "callisto-cli");
+        for invalid in ["", "Callisto", "callisto_cli", "-callisto", "callisto-", "callisto/tag"] {
+            assert!(ProductName::parse(invalid).is_err(), "{invalid} must be rejected");
+        }
+    }
