+    #[test]
+    fn product_release_rejects_non_semver_native_versions() {
+        let product = ProductName::parse("callisto").unwrap();
+        let pypi_compatible = Version::parse("1.2.3", VersionGrammar::Pep440).unwrap();
+        let pypi_only = Version::parse("1.2.3.post1", VersionGrammar::Pep440).unwrap();
+
+        assert!(matches!(
+            ProductReleaseId::new(product.clone(), pypi_compatible),
+            Err(ProductReleaseIdError::NonSemVer { grammar: VersionGrammar::Pep440 })
+        ));
+        assert!(matches!(
+            ProductReleaseId::new(product, pypi_only),
+            Err(ProductReleaseIdError::NonSemVer { grammar: VersionGrammar::Pep440 })
+        ));
+        assert!(Version::parse("1.2.3.post1", VersionGrammar::SemVer).is_err());
+    }
+
+    #[test]
+    fn product_release_rejects_ambiguous_or_noncanonical_wire_values() {
+        for invalid in ["callisto", "callisto@@1.2.3", "callisto@1.2", "Callisto@1.2.3"] {
+            assert!(ProductReleaseId::parse(invalid).is_err(), "{invalid} must be rejected");
+        }
+    }
